using System.Text;
using ChessFighter.Core;

namespace ChessFighter.Web.Game;

/// <summary>
/// 32x32 pixel-art piece sprites. The grids live in Sprites.Data.cs, generated by
/// chess-fighter/tools/make-sprites.py (re-run it to rebuild them from the shape definitions, or hand-edit the grids).
/// Legend:
///   '.' empty          'k' outline
///   '1'..'5' body ramp, dark to light (armour for P1, demon hide for P2)
///   'a'..'d' gold trim ramp, dark to light
///   'h' specular highlight   'e' eye / gem accent
/// Colours per side are CSS variables in fighter.css (.px-1 ... under .piece-svg.w / .piece-svg.b).
/// </summary>
public static partial class Sprites
{
    public const int Size = 32;

    public static string[] Rows(PieceType t)
    {
        switch (t)
        {
            case PieceType.Pawn: return Pawn;
            case PieceType.Rook: return Rook;
            case PieceType.Knight: return Knight;
            case PieceType.Bishop: return Bishop;
            case PieceType.Queen: return Queen;
            case PieceType.King: return King;
            default: return System.Array.Empty<string>();
        }
    }

    /// <summary>Horizontal runs of one colour, so a sprite is a couple of hundred rects instead of one per pixel.</summary>
    public static IEnumerable<(int X, int Y, int W, char C)> Runs(PieceType t)
    {
        var rows = Rows(t);
        int top = Size - rows.Length;
        for (int r = 0; r < rows.Length; r++)
        {
            var row = rows[r];
            int x = 0;
            while (x < row.Length)
            {
                char c = row[x];
                if (c == '.') { x++; continue; }
                int start = x;
                while (x < row.Length && row[x] == c) x++;
                yield return (start, top + r, x - start, c);
            }
        }
    }

    static readonly Dictionary<PieceType, string> markup = new();

    /// <summary>The sprite's rects as one cached SVG fragment, so 32 pieces on the board cost 32 strings, not thousands of nodes.</summary>
    public static string Body(PieceType t)
    {
        lock (markup)
        {
            if (markup.TryGetValue(t, out var s)) return s;
            var sb = new StringBuilder();
            foreach (var (x, y, w, c) in Runs(t))
                sb.Append("<rect x=\"").Append(x).Append("\" y=\"").Append(y).Append("\" width=\"").Append(w)
                  .Append("\" height=\"1\" class=\"px-").Append(c).Append("\"/>");
            return markup[t] = sb.ToString();
        }
    }
}
